/* ---------- unpack ---------- */
async function ungzip(b64){
  const bin = Uint8Array.from(atob(b64), c=>c.charCodeAt(0));
  if (typeof DecompressionStream === 'undefined')
    throw new Error('Browser too old — needs DecompressionStream (Chrome 80+ / Firefox 113+).');
  const s = new Blob([bin]).stream().pipeThrough(new DecompressionStream('gzip'));
  return await new Response(s).arrayBuffer();
}
function buildGeometry(buf, nv, nf){
  const q = new Uint16Array(buf, 0, nv*3);
  const idx = new Uint32Array(buf.slice(nv*6));
  const pos = new Float32Array(nv*3);
  for (let i=0;i<nv*3;i++) pos[i] = (q[i]/65535)*2 - 1;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos,3));
  g.setIndex(new THREE.BufferAttribute(idx,1));
  g.computeVertexNormals(); g.computeBoundingBox(); g.computeBoundingSphere();
  return g;
}

/* ---------- scene ---------- */
const renderer = new THREE.WebGLRenderer({antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth, innerHeight);
renderer.setClearColor(0x03070d,1);
document.getElementById('stage').appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x03070d, 0.055);
const camera = new THREE.PerspectiveCamera(42, innerWidth/innerHeight, 0.05, 400);
camera.position.set(2.05, 1.00, 2.70);
const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping=true; controls.dampingFactor=0.07;
controls.minDistance=1.1; controls.maxDistance=22; controls.autoRotateSpeed=0.85;
controls.autoRotate=true;

const composer = new THREE.EffectComposer(renderer);
composer.addPass(new THREE.RenderPass(scene,camera));
const bloom = new THREE.UnrealBloomPass(new THREE.Vector2(innerWidth,innerHeight),0.55,0.55,0.30);
composer.addPass(bloom);

/* ---------- materials ---------- */
const U = {uColor:{value:new THREE.Color(0x5fd8ee)}, uTime:{value:0}, uScan:{value:1.0}};

const VERT = `
varying vec3 vN; varying vec3 vV; varying vec3 vW;
void main(){
  vec4 mv = modelViewMatrix*vec4(position,1.0);
  vN = normalize(normalMatrix*normal); vV = normalize(-mv.xyz);
  vW = (modelMatrix*vec4(position,1.0)).xyz;
  gl_Position = projectionMatrix*mv;
}`;

/* SOLID: opaque, depth-writing, key light for form + hot fresnel rim.
   opaque means the ship actually blocks the grid behind it, which is what
   made the old additive-only version read as murky soup. */
const FRAG_SOLID = `
uniform vec3 uColor; uniform float uTime; uniform float uScan;
varying vec3 vN; varying vec3 vV; varying vec3 vW;
void main(){
  vec3 N = normalize(vN);
  float ndl  = clamp(dot(N, normalize(vec3(0.35,0.9,0.30))), 0.0, 1.0);
  float ndl2 = clamp(dot(N, normalize(vec3(-0.6,-0.2,-0.5))), 0.0, 1.0);
  float fres = pow(1.0 - abs(dot(N, normalize(vV))), 2.3);
  float sl   = 0.5 + 0.5*sin(vW.y*230.0 - uTime*1.4);
  sl = mix(1.0, sl, uScan*0.20);
  float sweep = fract(vW.y*0.30 - uTime*0.085);
  float band  = smoothstep(0.975,1.0,sweep)*uScan;
  vec3 c = uColor*(0.040 + ndl*0.20 + ndl2*0.055 + fres*1.15 + band*0.55);
  gl_FragColor = vec4(c*sl, 1.0);
}`;

/* HULL: a lit surface rather than a hologram. There is no texture to apply —
   the Fan Kit .ctm files carry geometry and one empty UV map, nothing else,
   which was checked file by file. So a "finish" here is shading, not a skin,
   and the panel says so rather than implying a real paint. */
const FRAG_HULL = `
uniform vec3 uColor; uniform float uTime;
varying vec3 vN; varying vec3 vV; varying vec3 vW;
void main(){
  vec3 N = normalize(vN), V = normalize(vV);
  vec3 L1 = normalize(vec3(0.45,0.80,0.40));    /* key, above and ahead */
  vec3 L2 = normalize(vec3(-0.75,0.20,-0.45));  /* cool fill from behind */
  vec3 L3 = normalize(vec3(0.0,-1.0,0.0));      /* bounce off the holo table */
  float d1 = clamp(dot(N,L1),0.0,1.0);
  float d2 = clamp(dot(N,L2),0.0,1.0);
  float d3 = clamp(dot(N,L3),0.0,1.0);
  float spec = pow(clamp(dot(reflect(-L1,N), V),0.0,1.0), 34.0);
  float fres = pow(1.0-abs(dot(N,V)), 3.0);
  /* Panel banding from world position. There is no texture to sample — the
     Fan Kit .ctm files carry geometry and one EMPTY uv map, checked file by
     file — so this is shading standing in for plating, not a paint job. */
  float band = 0.5 + 0.5*sin(vW.y*54.0 + vW.z*11.0);
  band = 1.0 + (smoothstep(0.90,1.0,band)-0.5)*0.10;
  vec3 grey = vec3(0.30,0.335,0.375);
  vec3 base = mix(grey, uColor*0.55, 0.22) * band;
  vec3 c = base*(0.34 + d1*0.86 + d2*0.34 + d3*0.14)
         + uColor*(spec*0.95 + fres*0.30);
  gl_FragColor = vec4(c, 1.0);
}`;

const matSolid = new THREE.ShaderMaterial({uniforms:U, vertexShader:VERT, fragmentShader:FRAG_SOLID,
  side:THREE.FrontSide, transparent:false, depthWrite:true});
const matHull  = new THREE.ShaderMaterial({uniforms:U, vertexShader:VERT, fragmentShader:FRAG_HULL,
  side:THREE.FrontSide, transparent:false, depthWrite:true});
const matDepth = new THREE.MeshBasicMaterial({colorWrite:false, depthWrite:true,
  polygonOffset:true, polygonOffsetFactor:1.2, polygonOffsetUnits:1.2});
const matEdges = new THREE.LineBasicMaterial({color:0x5fd8ee, transparent:true, opacity:0.44,
  blending:THREE.AdditiveBlending, depthWrite:false});
const matWire  = new THREE.MeshBasicMaterial({color:0x5fd8ee, wireframe:true, transparent:true,
  opacity:0.075, blending:THREE.AdditiveBlending, depthWrite:false});
const matPts   = new THREE.PointsMaterial({color:0x5fd8ee, size:0.0055, transparent:true,
  opacity:0.42, blending:THREE.AdditiveBlending, depthWrite:false, sizeAttenuation:true});

const MARKCOL = {gun:0xffaa3c, missile:0xff6b8a, countermeasure:0x7dffb4, mount:0x8fa6ff, other:0x9dcfdf};
const markMats = {};
Object.keys(MARKCOL).forEach(k=>{ markMats[k]=new THREE.MeshBasicMaterial({color:MARKCOL[k],
  transparent:true, opacity:0.92, blending:THREE.AdditiveBlending, depthWrite:false}); });
const matHot = new THREE.MeshBasicMaterial({color:0xffffff, transparent:true, opacity:1,
  blending:THREE.AdditiveBlending, depthWrite:false});

/* ---------- holo table ---------- */
const table = new THREE.Group();
const grid = new THREE.GridHelper(9,36,0x1d5f72,0x0f3644);
grid.material.transparent=true; grid.material.opacity=0.16; table.add(grid);
const ringMat = new THREE.MeshBasicMaterial({color:0x5fd8ee, transparent:true, opacity:0.20,
  side:THREE.DoubleSide, blending:THREE.AdditiveBlending, depthWrite:false});
const ring = new THREE.Mesh(new THREE.RingGeometry(1.45,1.50,128), ringMat);
ring.rotation.x = -Math.PI/2; table.add(ring);
scene.add(table);

/* ---------- state ---------- */
const cache = {};
let current = 0, mode = 'panel', occlude = true, detail = 24, lineInt = 1.0;
let showHP = true, mirror = false, selected = null, hovered = null;
let allLabels = false, autoFrame = true;
const filter = {gun:true, missile:true, countermeasure:true, turret:true};
const holder = new THREE.Group(); scene.add(holder);
const markGroup = new THREE.Group(); scene.add(markGroup);
let pickMesh = null;

function edgeOpacity(edgeCount){
  const o = 0.44 * Math.pow(168351/edgeCount, 0.85);
  return Math.min(0.55, Math.max(0.12, o)) * lineInt;
}
function edgesFor(i, deg){
  const k = 'e'+deg;
  if (!cache[i][k]) cache[i][k] = new THREE.EdgesGeometry(cache[i].geo, deg);
  return cache[i][k];
}
function clearGroup(g){ while(g.children.length) g.remove(g.children[0]); }

function show(i){
  current = i; selected = null;
  const s = SHIPS[i], g = cache[i].geo;
  clearGroup(holder);

  pickMesh = new THREE.Mesh(g, matDepth);
  pickMesh.visible = occlude && (mode === 'panel' || mode === 'wire');
  pickMesh.renderOrder = 0;
  holder.add(pickMesh);

  if (mode === 'solid' || mode === 'solidlines'){
    const m = new THREE.Mesh(g, matSolid); m.renderOrder = 1; holder.add(m);
  }
  if (mode === 'hull'){
    const m = new THREE.Mesh(g, matHull); m.renderOrder = 1; holder.add(m);
  }
  if (mode === 'panel' || mode === 'solidlines'){
    const eg = edgesFor(i, detail);
    matEdges.opacity = edgeOpacity(eg.attributes.position.count/2)
                       * (mode==='solidlines' ? 0.75 : 1);
    const l = new THREE.LineSegments(eg, matEdges); l.renderOrder = 2; holder.add(l);
  }
  if (mode === 'wire')   { const m=new THREE.Mesh(g,matWire);  m.renderOrder=2; holder.add(m); }
  if (mode === 'points') { const p=new THREE.Points(g,matPts); p.renderOrder=2; holder.add(p); }

  if (cache[i].minY === undefined) cache[i].minY = g.boundingBox.min.y;
  holder.position.y = -cache[i].minY + 0.04;
  markGroup.position.copy(holder.position);

  const m = s.dims.map(v=>(v/100).toFixed(1));
  const hps = HARDPT[s.name] || [];
  document.getElementById('shipName').textContent = s.name;
  document.getElementById('shipStats').innerHTML =
    `<b>${m[2]} m</b> long &nbsp;·&nbsp; <b>${m[0]} m</b> wide &nbsp;·&nbsp; <b>${m[1]} m</b> tall<br>` +
    `${s.nv.toLocaleString()} vertices &nbsp;·&nbsp; ${s.nf.toLocaleString()} triangles &nbsp;·&nbsp; <b>${hps.length}</b> hardpoints<br>` +
    `geometry: CIG Fan Kit <i>.ctm</i> &nbsp;·&nbsp; loadout: <i>ships.json</i> 20260801Z`;

  [...document.querySelectorAll('#ships button')].forEach((b,j)=>b.classList.toggle('on', j===i));
  buildLoadout(i);
  rebuildMarkers();
  closeDetail();
  frameShip(i);
}

/* ---------- hardpoints ----------
   Fixed, not placed by clicking. Every marker sits where the mount NAME and
   the hull shape put it, and clicking one opens what is fitted there.

   Where the position comes from, said plainly because it matters: CIG's data
   carries a `position` field for every one of these mounts and every single
   one of the 53,651 of them is null. So nobody — us, Erkul, anyone — has real
   coordinates. What the data DOES carry is the mount's name, and those names
   are locations: "Weapon left wing", "Gun laser bottom right", "Left Pylon 2".
   Those words plus the hull mesh give a position that is right about where
   the gun is. It is derived. It is not CIG's. The panel says so every time. */
const labelsEl = document.getElementById('labels');
function visibleHP(){
  return (HARDPT[SHIPS[current].name]||[]).filter(h=>{
    if (h.turretOf) return filter.turret;
    return filter[h.kind] !== false && (h.kind in filter ? filter[h.kind] : true);
  });
}
function markerSize(h){
  const s = Math.max(...h.items.map(i=>i.size||1));
  return 0.014 + Math.min(s,7)*0.0028;
}
function rebuildMarkers(){
  clearGroup(markGroup);
  labelsEl.innerHTML = '';
  if (!showHP) return;
  visibleHP().forEach(h=>{
    const geo = h.kind==='missile' ? new THREE.BoxGeometry(markerSize(h)*1.5,markerSize(h),markerSize(h)*1.5)
                                   : new THREE.OctahedronGeometry(markerSize(h));
    const m = new THREE.Mesh(geo, markMats[h.kind]||markMats.other);
    m.position.set(h.unit[0]*(mirror?-1:1), h.unit[1], h.unit[2]);
    m.userData.hp = h;
    markGroup.add(m);
    const d = document.createElement('div');
    d.className = 'hp' + (h.turretOf ? ' turret' : '');
    const lead = h.items.find(i=>i.dps) || h.items[0];
    d.innerHTML = '<b>'+esc(lead.name)+'</b><br>'+esc(sideLabel(h.where));
    labelsEl.appendChild(d); h._el = d; h._mesh = m;
  });
  applyHot();
}
const esc = s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
/* Mirroring has to flip the WORD as well as the marker, or the label and the
   dot disagree and the viewer is lying twice instead of once. */
function sideLabel(w){
  if (!mirror) return w;
  return String(w).replace(/\b(left|right|Left|Right)\b/g, m=>
    (m.toLowerCase()==='left' ? (m[0]==='L'?'Right':'right') : (m[0]==='R'?'Left':'left')));
}
function applyHot(){
  markGroup.children.forEach(m=>{
    const h = m.userData.hp;
    const on = (selected && h===selected) || (hovered && h===hovered);
    m.material = on ? matHot : (markMats[h.kind]||markMats.other);
    m.scale.setScalar(on ? 1.8 : 1);
    if (h._el){
      h._el.classList.toggle('hot', !!on);
      h._el.classList.toggle('dim', !!selected && !on);
    }
  });
}
/* Fifteen labels at once is a wall of text — the Cutlass proved that: every
   marker was right and none of them was readable. So a label only appears for
   the marker you are pointing at or have opened, unless you ask for all of
   them. The dots stay; it is the words that had to go quiet. */
function updateLabels(){
  const list = visibleHP();
  if (!list.length) return;
  const v = new THREE.Vector3();
  const camDir = camera.position.clone().sub(controls.target).normalize();
  list.forEach(h=>{
    if (!h._el || !h._mesh) return;
    const want = allLabels || h===selected || h===hovered;
    if (!want){ h._el.style.display='none'; return; }
    v.copy(h._mesh.position).add(markGroup.position).project(camera);
    if (v.z > 1){ h._el.style.display='none'; return; }
    h._el.style.display='block';
    h._el.style.left = ((v.x*0.5+0.5)*innerWidth)+'px';
    h._el.style.top  = ((-v.y*0.5+0.5)*innerHeight)+'px';
  });
  /* A marker on the far side of the hull reads as if it were on this side.
     Fade it instead of hiding it, so the ship still shows what it carries
     without pretending the back of it is the front. */
  markGroup.children.forEach(m=>{
    const facing = m.position.clone().normalize().dot(camDir);
    const back = facing < -0.15;
    m.material.opacity = (m.material===matHot) ? 1 : (back ? 0.30 : 0.92);
  });
}

/* Frame each hull so a 24 m Sabre and a 61 m Constellation both fill the
   view — otherwise the big ship looks distant and the small one enormous. */
let framedShip = -1;
function frameShip(i, force){
  /* only on a ship change — re-framing every time a slider moves would yank
     the camera out from under someone adjusting line detail */
  if (!autoFrame || (i === framedShip && !force)) return;
  framedShip = i;
  const g = cache[i].geo;
  const r = g.boundingSphere ? g.boundingSphere.radius : 1;
  /* Fit to whichever field of view is tighter. The horizontal one is wider on
     a normal window, so fitting only to the vertical leaves the ship small —
     which is what the first attempt did to the Constellation. */
  const vfov = THREE.MathUtils.degToRad(camera.fov*0.5);
  const hfov = Math.atan(Math.tan(vfov) * camera.aspect);
  const d = r / Math.sin(Math.min(vfov, hfov)) * 0.92;
  const dir = new THREE.Vector3(0.62,0.30,0.82).normalize();
  controls.target.set(0, holder.position.y*0.5, 0);
  camera.position.copy(dir.multiplyScalar(d)).add(controls.target);
  controls.update();
}

/* ---------- the detail panel ---------- */
const ROLE = {WeaponGun:'GUN', MissileLauncher:'MISSILE RACK', WeaponDefensive:'COUNTERMEASURE',
              Turret:'MOUNT'};
function openDetail(h){
  selected = h; applyHot();
  const L = LOADOUT[SHIPS[current].name];
  document.getElementById('hpdTitle').textContent = sideLabel(h.where);
  document.getElementById('hpdTag').innerHTML = h.turretOf
    ? '<span class="tur">TURRET — NOT PILOT-CONTROLLED</span>'
    : (h.pilot ? 'PILOT-CONTROLLED' : '');
  const totalDps = h.items.reduce((a,i)=>a+(i.dps||0),0);
  document.getElementById('hpdBody').innerHTML = h.items.map(i=>`
    <div class="fit">
      <div class="role">${esc(ROLE[i.type]||i.type)}</div>
      <h4>${esc(i.name)}</h4>
      <div class="meta">Size ${i.size ?? '—'}${i.mfr?' · '+esc(i.mfr):''}<br>
        <span style="color:#4d7688">${esc(i.port||'')}</span></div>
      ${(i.dps||i.alpha)?`<div class="nums">
        <div>DPS<b>${i.dps ?? '—'}</b></div>
        <div>ALPHA<b>${i.alpha ?? '—'}</b></div></div>`:''}
    </div>`).join('')
    + (h.kind==='missile' && L.missiles && L.missiles.length ? `
    <div class="fit"><div class="role">CARRIED</div>
      <h4>${L.missiles.map(m=>esc(m.count+'× '+m.name)).join('<br>')}</h4>
      <div class="meta">ship total across every rack, not this rack alone — the
        data gives a total and does not split it per pylon</div></div>` : '');
  const cm = h.pos.map(v=>(v/100).toFixed(1));
  document.getElementById('hpdFoot').innerHTML =
    (totalDps?`<b>${totalDps.toFixed(1)} DPS</b> at this hardpoint. `:'')
    + `Position ${cm[0]} / ${cm[1]} / ${cm[2]} m from hull centre — <b>derived</b> from the words
       "${esc(h.read.join(', '))}" in the mount name plus the hull shape.
       CIG's own data has this coordinate as null for all 53,651 mounts, so no one has the real one.
       Left and right assume a right-handed model; use Mirror L/R if your ship looks flipped.`;
  document.getElementById('hpd').classList.add('show');
  document.querySelectorAll('#lo .it').forEach(n=>
    n.classList.toggle('sel', n.dataset.where===h.where));
}
function closeDetail(){ selected=null; applyHot();
  document.getElementById('hpd').classList.remove('show');
  document.querySelectorAll('#lo .it').forEach(n=>n.classList.remove('sel')); }
document.getElementById('hpdClose').onclick = closeDetail;

const ray = new THREE.Raycaster(), ndc = new THREE.Vector2();
let downAt = null;
function markerUnder(cx, cy){
  ndc.x = (cx/innerWidth)*2-1;
  ndc.y = -(cy/innerHeight)*2+1;
  ray.setFromCamera(ndc, camera);
  const hit = ray.intersectObjects(markGroup.children, false)[0];
  return hit ? hit.object.userData.hp : null;
}
renderer.domElement.addEventListener('pointerdown', e=>{ downAt=[e.clientX,e.clientY]; });
renderer.domElement.addEventListener('pointermove', ev=>{
  const h = markerUnder(ev.clientX, ev.clientY);
  if (h !== hovered){ hovered = h; applyHot();
    renderer.domElement.style.cursor = h ? 'pointer' : ''; }
});
renderer.domElement.addEventListener('pointerup', ev=>{
  /* a drag is an orbit, not a click — without this every rotate closes the panel */
  if (!downAt || Math.hypot(ev.clientX-downAt[0], ev.clientY-downAt[1]) > 5) return;
  const h = markerUnder(ev.clientX, ev.clientY);
  if (h) openDetail(h); else closeDetail();
});

/* ---------- loadout list ---------- */
function buildLoadout(i){
  const el = document.getElementById('lo');
  const L  = LOADOUT[SHIPS[i].name];
  if (!L){ el.innerHTML='<div class="sec">NO LOADOUT DATA FOR THIS HULL</div>'; return; }
  const hps = HARDPT[SHIPS[i].name] || [];
  let h='';

  if (!hps.length){
    h += `<div class="sec">HARDPOINTS</div><div class="it"><span class="nm" style="color:#5c869a">
      This hull carries no weapon mounts in the data — nothing to mark on it.</span></div>`;
  } else {
    const pilot  = hps.filter(x=>x.pilot && !x.turretOf);
    const turret = hps.filter(x=>x.turretOf);
    const rest   = hps.filter(x=>!x.pilot && !x.turretOf);
    const row = x=>{
      const lead = x.items.find(i=>i.dps) || x.items[0];
      const dps  = x.items.reduce((a,i)=>a+(i.dps||0),0);
      const st   = dps ? dps.toFixed(1)+' dps'
                       : (x.kind==='missile'?'rack':(x.kind==='countermeasure'?'CM':'mount'));
      const gim  = x.items.find(i=>i.type==='Turret' && /gimbal/i.test(i.name));
      return `<div class="it arm" data-where="${esc(x.where)}">
        <span class="nm"><span class="where">${esc(sideLabel(x.where))}</span>${esc(lead.name)}
          <small>S${lead.size}${lead.mfr?' · '+esc(lead.mfr):''}${gim?' · on a gimbal':''}
            ${x.turretOf?' <span class="tur">TURRET</span>':(x.pilot?' <span class="pin">PILOT</span>':'')}</small>
        </span><span class="st">${st}</span></div>`;
    };
    h += `<div class="sec">PILOT HARDPOINTS — ${L.pilotDps ?? '—'} TOTAL DPS</div>`;
    h += pilot.length ? pilot.map(row).join('')
                      : '<div class="it"><span class="nm" style="color:#5c869a">none</span></div>';
    if (turret.length) h += `<div class="sec">TURRET GUNS — SOMEONE ELSE FIRES THESE</div>`+turret.map(row).join('');
    if (rest.length)   h += `<div class="sec">OTHER MOUNTS</div>`+rest.map(row).join('');
  }

  if (L.missiles && L.missiles.length){
    h += `<div class="sec">MISSILES — CARRIED ON THE RACKS ABOVE</div>`;
    L.missiles.forEach(m=>{ h += `<div class="it"><span class="qty">${m.count}×</span>
      <span class="nm">${esc(m.name)}<small>S${m.size}</small></span></div>`; });
  }

  /* Internal components deliberately get a list rather than hull markers: the
     standing project decision is that anything you never physically walk up to
     belongs in a menu overlay, not stuck on the hull. */
  h += `<div class="sec">COMPONENTS — MENU OVERLAY, NOT HULL-MOUNTED</div>`;
  let grp=null;
  L.components.forEach(c=>{
    if (c.group!==grp){ grp=c.group;
      h += `<div class="it"><span class="nm" style="color:#4f7a8c;font-size:9.5px;letter-spacing:.14em">${esc(grp.toUpperCase())}</span></div>`; }
    let extra='';
    if (c.hp)    extra=c.hp.toLocaleString()+' hp';
    if (c.speed) extra=(c.speed/1000).toFixed(0)+' km/s';
    h += `<div class="it"><span class="qty">${c.count}×</span>
      <span class="nm">${esc(c.name)}<small>S${c.size??'—'}${c.mfr?' · '+esc(c.mfr):''}</small></span>
      <span class="st">${extra}</span></div>`;
  });
  el.innerHTML=h;

  el.querySelectorAll('.it.arm').forEach(node=>{
    node.onclick=()=>{
      const hp = (HARDPT[SHIPS[current].name]||[]).find(x=>x.where===node.dataset.where);
      if (hp) openDetail(hp);
    };
  });
}

/* ---------- UI ---------- */
const shipsEl=document.getElementById('ships');
SHIPS.forEach((s,i)=>{const b=document.createElement('button');b.className='ship';
  b.textContent=s.name;b.onclick=()=>show(i);shipsEl.appendChild(b);});

const MODES=[['panel','Panel lines'],['solidlines','Solid + lines'],['solid','Solid holo'],
             ['hull','Lit hull'],['wire','Wireframe'],['points','Points']];
const modesEl=document.getElementById('modes');
MODES.forEach(([k,lab])=>{const b=document.createElement('button');b.textContent=lab;
  if(k==='panel')b.classList.add('on');
  b.onclick=()=>{mode=k;[...modesEl.children].forEach(x=>x.classList.remove('on'));
    b.classList.add('on');show(current);};
  modesEl.appendChild(b);});

const COLOURS=[0x5fd8ee,0x7dffb4,0xffb545,0xff6b8a,0xe8f4ff];
const colsEl=document.getElementById('cols');
COLOURS.forEach((hex,i)=>{const b=document.createElement('button');b.className='sw';
  b.style.background='#'+hex.toString(16).padStart(6,'0');if(i===0)b.classList.add('on');
  b.onclick=()=>{[...colsEl.children].forEach(x=>x.classList.remove('on'));b.classList.add('on');
    const c=new THREE.Color(hex);U.uColor.value=c;matEdges.color=c;matWire.color=c;
    matPts.color=c;ringMat.color=c;};
  colsEl.appendChild(b);});

const $=id=>document.getElementById(id);
$('lineInt').oninput=e=>{lineInt=e.target.value/100;$('vInt').textContent=e.target.value+'%';show(current);};
$('detail').oninput =e=>{detail=+e.target.value;$('vDet').textContent=detail+'°';show(current);};
$('bloom').oninput  =e=>{bloom.strength=e.target.value/100;$('vGlow').textContent=(e.target.value/100).toFixed(2);};
$('spin').onclick=e=>{controls.autoRotate=!controls.autoRotate;e.target.classList.toggle('on',controls.autoRotate);};
$('grid').onclick=e=>{table.visible=!table.visible;e.target.classList.toggle('on',table.visible);};
$('scan').onclick=e=>{const on=U.uScan.value<0.5;U.uScan.value=on?1:0;e.target.classList.toggle('on',on);};
$('occ').onclick =e=>{occlude=!occlude;e.target.classList.toggle('on',occlude);show(current);};
$('loT').onclick =e=>{$('lo').classList.toggle('hide');e.target.classList.toggle('on',!$('lo').classList.contains('hide'));};

$('hpOn').onclick=e=>{showHP=!showHP;e.target.classList.toggle('on',showHP);rebuildMarkers();if(!showHP)closeDetail();};
const FILTBTN={fGun:'gun',fMis:'missile',fCm:'countermeasure',fTur:'turret'};
Object.keys(FILTBTN).forEach(id=>{ $(id).onclick=e=>{
  const k=FILTBTN[id]; filter[k]=!filter[k]; e.target.classList.toggle('on',filter[k]);
  rebuildMarkers(); if(selected && !visibleHP().includes(selected)) closeDetail(); };});
$('mirror').onclick=e=>{mirror=!mirror;e.target.classList.toggle('on',mirror);
  rebuildMarkers();buildLoadout(current);if(selected)openDetail(selected);};
$('allLbl').onclick=e=>{allLabels=!allLabels;e.target.classList.toggle('on',allLabels);};
$('frame').onclick=e=>{autoFrame=!autoFrame;e.target.classList.toggle('on',autoFrame);
  if(autoFrame) frameShip(current,true);};

$('exp').onclick=()=>{
  const s=SHIPS[current];
  const doc={schema:'citizen-compass.hardpoints/2', ship:s.name,
    source_model:'CIG Fan Kit .ctm',
    derivation:'positions derived from mount-name vocabulary + hull geometry; '+
               'CIG position fields are null for all 53,651 mounts',
    handedness_assumed:'forward -Z, up +Y, right +X',
    model_space:'origin-centred cube, longest axis spans -1..1; pos_cm is centimetres from hull centre',
    hardpoints:(HARDPT[s.name]||[]).map(h=>({where:h.where,kind:h.kind,pilot:h.pilot,
      turretOf:h.turretOf,derived_from:h.read,pos_cm:h.pos,pos_unit:h.unit,
      items:h.items}))};
  const b=new Blob([JSON.stringify(doc,null,2)],{type:'application/json'});
  const a=document.createElement('a');a.href=URL.createObjectURL(b);
  a.download='hardpoints_'+s.name.replace(/\W+/g,'_').toLowerCase()+'.json';a.click();
};

addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);composer.setSize(innerWidth,innerHeight);});

/* ---------- boot ---------- */
const clock=new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  U.uTime.value=clock.getElapsedTime();
  ring.rotation.z+=0.0016;
  markGroup.children.forEach(m=>{m.rotation.y+=0.03;m.rotation.x+=0.017;});
  controls.update(); composer.render(); updateLabels();
}
(async function boot(){
  const barI=document.querySelector('#bar i'), msg=$('lmsg');
  try{
    for(let i=0;i<SHIPS.length;i++){
      msg.textContent='unpacking '+SHIPS[i].name+'…';
      const buf=await ungzip(SHIPS[i].b64);
      cache[i]={geo:buildGeometry(buf,SHIPS[i].nv,SHIPS[i].nf)};
      SHIPS[i].b64=null;
      barI.style.width=((i+1)/SHIPS.length*100)+'%';
      await new Promise(r=>setTimeout(r,0));
    }
    show(0); animate(); $('load').classList.add('gone');
  }catch(err){ msg.innerHTML='<span style="color:#ff8080">'+err.message+'</span>'; }
})();
